style.css:
@-moz-document domain("roblox.com") {
/* 1. GŁÓWNE TŁO */
    body, 
    .dark-theme, 
    .light-theme, 
    #container-main, 
    .background-container {
        background-image: url("https://redd.it") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center top !important;
        background-repeat: no-repeat !important;
        /* Efekt czarno-biały i lekkie przyciemnienie nałożone bezpośrednio */
        filter: grayscale(100%) brightness(60%) !important;
    }

    /* 2. PRZEZROCZYSTOŚĆ ELEMENTÓW (żeby widzieć postać) */
    .container-main, 
    .section-content, 
    .rbx-header,
    .content,
    .left-col-list,
    .place-container,
    #navigation {
        background: rgba(0, 0, 0, 0.5) !important; /* Półprzezroczysta czerń */
        border: none !important;
    }

    /* 3. USUWANIE BIAŁYCH TŁA POD GRAMI */
    .game-card-container, 
    .item-card-container, 
    .card-item {
        background: transparent !important;
        border: none !important;
    }

    /* 4. UKRYWANIE REKLAM (czystszy wygląd) */
    .ad-container, 
    .abp, 
    #AdvertisingLeaderboard {
        display: none !important;
    }

    /* 5. POPRAWKA TEKSTU */
    .text-title, .text-name {
        color: #ffffff !important;
        text-shadow: 1px 1px 2px #000; /* Cień pod tekstem dla lepszej czytelności */
    }
}
